"""Output linter for an emitted `.claude/` tree.

Walks the output directory after `harness generate` and reports violations of the
rules enumerated in plan §13 (F-001..F-052). Each rule is a small function that
yields zero or more `Finding` records. The linter is independent of the emitter —
it only reads files on disk so it also catches drift introduced by hand edits.
"""

from __future__ import annotations

import json
import os
import re
from collections.abc import Iterator
from dataclasses import dataclass
from pathlib import Path

from ruamel.yaml import YAML

# ---- finding records --------------------------------------------------------

Severity = str  # "error" | "warn"


@dataclass(frozen=True)
class Finding:
    rule: str  # e.g. "F-002"
    severity: Severity
    file: Path
    message: str

    def format(self) -> str:
        sev_marker = "ERROR" if self.severity == "error" else "warn"
        return f"{self.rule:<6} {sev_marker:<5} {self.file}: {self.message}"


@dataclass
class LintReport:
    findings: list[Finding]

    def errors(self) -> list[Finding]:
        return [f for f in self.findings if f.severity == "error"]

    def warnings(self) -> list[Finding]:
        return [f for f in self.findings if f.severity == "warn"]

    def passed(self, *, strict: bool) -> bool:
        if self.errors():
            return False
        return not (strict and self.warnings())


# ---- frontmatter helpers ----------------------------------------------------

_FRONTMATTER_RE = re.compile(r"\A---\s*\n(.*?)\n---\s*\n(.*)\Z", re.DOTALL)


def _parse_frontmatter(text: str) -> tuple[dict, str] | None:
    m = _FRONTMATTER_RE.match(text)
    if not m:
        return None
    try:
        yaml = YAML(typ="safe")
        fm = yaml.load(m.group(1)) or {}
    except Exception:
        return None
    return fm, m.group(2)


def _safe_read(path: Path) -> str | None:
    try:
        return path.read_text(encoding="utf-8")
    except OSError:
        return None


# ---- the rules --------------------------------------------------------------


def lint_output(out_dir: Path, *, mcp_path: Path | None = None) -> LintReport:
    """Run every rule against an emitted `.claude/` tree under `out_dir`."""
    project_dir = out_dir / ".claude"
    findings: list[Finding] = []
    if not project_dir.is_dir():
        # nothing to lint; return empty (caller decides whether that is ok)
        return LintReport(findings=findings)

    skill_files = sorted(project_dir.glob("skills/*/SKILL.md"))
    agent_files = sorted(project_dir.glob("agents/*.md"))
    rule_files = sorted(p for p in project_dir.rglob("rules/**/*.md"))
    hook_files = sorted(project_dir.glob("hooks/*"))
    settings_file = project_dir / "settings.json"
    mcp_path = mcp_path if mcp_path is not None else (out_dir / ".mcp.json")

    settings: dict | None = None
    if settings_file.is_file():
        try:
            settings = json.loads(settings_file.read_text(encoding="utf-8"))
        except json.JSONDecodeError as e:
            findings.append(Finding(
                "F-005", "error", settings_file,
                f"settings.json is not valid JSON: {e}",
            ))
    mcp_servers: dict[str, dict] = {}
    if mcp_path.is_file():
        try:
            mcp_servers = json.loads(mcp_path.read_text(encoding="utf-8")).get("mcpServers", {})
        except json.JSONDecodeError as e:
            findings.append(Finding(
                "F-007", "error", mcp_path, f".mcp.json is not valid JSON: {e}",
            ))

    for f in skill_files:
        findings.extend(_lint_skill_file(f))
    for f in agent_files:
        findings.extend(_lint_agent_file(f, mcp_servers))
    for f in rule_files:
        findings.extend(_lint_rule_file(f))
    for f in hook_files:
        findings.extend(_lint_hook_file(f))

    if settings is not None:
        findings.extend(_lint_settings(settings, settings_file, mcp_servers))
    findings.extend(_lint_mcp(mcp_servers, mcp_path))

    # global TODO counter (F-013)
    findings.extend(_lint_todos(project_dir))

    # F-046: validation-agent has no <runner>-patterns skill ref → no E2E coverage
    findings.extend(_lint_e2e_coverage(project_dir))

    # F-047 — F-050: Requirement Phase v2 (plan §21-K)
    findings.extend(_lint_story_priority_independent_test(project_dir))
    findings.extend(_lint_state_file_schema_v2(project_dir))
    findings.extend(_lint_sync_skill_required_refs(project_dir))
    findings.extend(_lint_prd_open_questions_clarification_consistency(project_dir))

    # F-051: PRD / PLAN section pinning (plan §24)
    findings.extend(_lint_prd_plan_section_pinning(project_dir))

    # F-052: context-economy mechanism must ship (read-dedup hook + rule)
    findings.extend(_lint_context_economy_present(project_dir, settings))

    return LintReport(findings=findings)


_E2E_RUNNERS = {"playwright", "maestro", "cypress", "selenium"}


def _lint_e2e_coverage(project_dir: Path) -> Iterator[Finding]:
    """F-046: validation-agent should reference at least one E2E runner pattern when
    the project has UI / API surfaces. Catches the common gap of `jest-patterns`
    being the only validation skill — jest does not run E2E."""
    val = project_dir / "agents" / "validation-agent.md"
    if not val.is_file():
        return
    text = _safe_read(val) or ""
    parsed = _parse_frontmatter(text)
    if not parsed:
        return
    fm, _ = parsed
    skills = fm.get("skills") or []
    if isinstance(skills, str):
        skills = skills.split()
    has_e2e_runner = any(
        any(s.startswith(f"{r}-") for r in _E2E_RUNNERS) for s in skills
    )
    if has_e2e_runner:
        return
    # only warn if the project has any UI / API role surface — pure data / library
    # projects may legitimately skip E2E
    rules_dir = project_dir / "rules"
    has_ui_or_api = any(rules_dir.glob("**/*.md")) and any(
        # heuristic: per-stack rules drop perf-budgets, app-router, pydantic, etc.
        f.name in {"app-router.md", "perf-budgets.md", "pydantic-models.md",
                   "react-native-perf.md", "fastapi-patterns.md"}
        for f in rules_dir.rglob("*.md")
    )
    if has_ui_or_api or any(s in {"jest-patterns", "vitest-patterns", "pytest-patterns"}
                            for s in skills):
        yield Finding(
            "F-046", "warn", val,
            "validation-agent has no E2E runner skill (playwright/maestro/cypress); "
            "add a test-automation stack via `harness add stack playwright:1.48` "
            "(or maestro / cypress).",
        )


# ---- skill rules -----------------------------------------------------------

_NAME_RE = re.compile(r"^[a-z0-9-]{1,64}$")


def _lint_skill_file(path: Path) -> Iterator[Finding]:
    text = _safe_read(path)
    if text is None:
        return
    parsed = _parse_frontmatter(text)
    if parsed is None:
        yield Finding("F-001", "error", path, "SKILL.md missing YAML frontmatter")
        return
    fm, body = parsed

    # F-001: name + description
    if "description" not in fm:
        yield Finding("F-001", "error", path, "frontmatter missing 'description'")
    name = fm.get("name") or path.parent.name
    if not _NAME_RE.fullmatch(name):
        yield Finding("F-018", "error", path, f"name {name!r} must match [a-z0-9-]{{1,64}}")

    desc = fm.get("description") or ""
    when = fm.get("when_to_use") or ""

    # F-002 / F-003
    if len(desc) > 200:
        yield Finding("F-002", "warn", path, f"description is {len(desc)} chars (recommend ≤200)")
    if len(desc) + len(when) > 1536:
        yield Finding(
            "F-003", "error", path,
            f"description + when_to_use is {len(desc) + len(when)} chars (Anthropic cap 1536)",
        )

    # F-011: starts with verb (heuristic)
    if desc and desc.lower().startswith(("use this skill to", "this skill")):
        yield Finding("F-011", "warn", path, "description should start with verb, not 'Use this skill to…'")

    # F-019: $name placeholders match `arguments`
    args = fm.get("arguments")
    if isinstance(args, str):
        args = args.split()
    if args:
        for arg in args:
            if f"${arg}" not in body and "$ARGUMENTS" not in body:
                yield Finding("F-019", "warn", path, f"argument {arg!r} declared but ${arg} not used in body")

    # F-020: context: fork requires agent
    if fm.get("context") == "fork" and not fm.get("agent"):
        yield Finding("F-020", "error", path, "context: fork requires `agent:` field")

    # F-021: heuristic — body uses tools but no allowed-tools declared
    if fm.get("allowed-tools") is None and re.search(
        r"\bBash\(|\bRead\(|\bGrep\(|\bWrite\(|\bEdit\(|\bmcp__", body
    ):
        yield Finding(
            "F-021", "warn", path,
            "body invokes tools but no `allowed-tools` declared — user will be prompted",
        )

    # F-031: workflow command (disable-model-invocation: true) must reference an agent
    # OR demonstrate a clear procedure (numbered steps with concrete actions). Pure
    # no-op skills are silently broken at runtime, so we require one or the other.
    if fm.get("disable-model-invocation"):
        has_agent_ref = bool(re.search(
            r"\b(agent[- ]|Invoke|Delegate|subagent|delegate to|hand off|hand over)\b",
            body, re.IGNORECASE,
        ))
        has_procedure = bool(re.search(
            r"^\s*\d+\.\s+\S", body, re.MULTILINE,
        ))
        if not (has_agent_ref or has_procedure):
            yield Finding(
                "F-031", "error", path,
                "workflow command body must reference an agent or contain a numbered procedure",
            )

    # F-032: legacy commands path (warning when emitted under .claude/commands/)
    if "commands" in path.parts and path.suffix == ".md" and path.name != "SKILL.md":
        yield Finding(
            "F-032", "warn", path,
            "skill emitted to legacy `.claude/commands/` path; prefer `.claude/skills/<n>/SKILL.md`",
        )


# ---- agent rules -----------------------------------------------------------

_AGENT_NAME_RE = re.compile(r"^[a-z][a-z0-9-]{0,63}$")
_VALID_MODEL_TIERS = {"opus", "sonnet", "haiku", "inherit"}


def _lint_agent_file(path: Path, mcp_servers: dict[str, dict]) -> Iterator[Finding]:
    text = _safe_read(path)
    if text is None:
        return
    parsed = _parse_frontmatter(text)
    if parsed is None:
        yield Finding("F-001", "error", path, "agent file missing YAML frontmatter")
        return
    fm, body = parsed

    name = fm.get("name")
    if not name or not _AGENT_NAME_RE.fullmatch(str(name)):
        yield Finding("F-022", "error", path, f"agent name {name!r} must match ^[a-z][a-z0-9-]{{0,63}}$")
    desc = fm.get("description") or ""
    if not desc:
        yield Finding("F-001", "error", path, "agent missing required 'description'")
    if len(desc) > 120:
        yield Finding("F-027", "warn", path, f"description is {len(desc)} chars (recommend ≤120)")

    # F-004: model declared
    model = fm.get("model")
    if model is None:
        yield Finding("F-004", "error", path, "agent must declare `model:` (enterprise hygiene)")
    elif (
        isinstance(model, str)
        and "/" not in model
        and "-" not in model
        # Not a fully-qualified ID — must be a known tier
        and model not in _VALID_MODEL_TIERS
    ):
        yield Finding(
            "F-004", "error", path,
            f"model {model!r} not in {_VALID_MODEL_TIERS} or a fully-qualified ID",
        )

    # F-014: body length
    body_lines = [line for line in body.splitlines() if line.strip()]
    if len(body_lines) > 80:
        yield Finding(
            "F-014", "error", path,
            f"agent body is {len(body_lines)} non-blank lines (max 80; move knowledge to skills)",
        )

    # F-015 / F-024: skill linkage. The skill name MUST follow a strong cue
    # (`Load skill:`, `Use skill:`, `skill `<name>``, or appear in a `skills/<name>` path).
    # Plain "skill X" without a colon or backtick is too noisy and was producing
    # false positives like "skill is preloaded" → capturing "is".
    referenced: set[str] = set()
    referenced |= {m.group(1) for m in re.finditer(
        r"(?:Load|Use|Invoke|Apply)\s+skill[:\s]+`?([a-z][a-z0-9-]+)`?",
        body, re.IGNORECASE,
    )}
    referenced |= {m.group(1) for m in re.finditer(
        r"skill\s+`([a-z][a-z0-9-]+)`",
        body, re.IGNORECASE,
    )}
    referenced |= {m.group(1) for m in re.finditer(r"`skills/([a-z][a-z0-9-]+)`", body)}
    # Match `.claude/skills/<name>/SKILL.md` (the canonical reference) only —
    # NOT `.claude/skills/<name>/steps/…` which is the agent's own sub-file path.
    referenced |= {m.group(1) for m in re.finditer(
        r"\.claude/skills/([a-z][a-z0-9-]+)/SKILL\.md", body,
    )}
    declared = set()
    skills_field = fm.get("skills")
    if isinstance(skills_field, str):
        declared = set(skills_field.split())
    elif isinstance(skills_field, list):
        declared = {str(s) for s in skills_field}

    # Only flag F-015 if body suggests delegation
    if (
        not referenced
        and not declared
        and re.search(r"\b(load skill|use skill|invoke|delegate)\b", body, re.IGNORECASE)
    ):
        yield Finding(
            "F-015", "error", path,
            "agent body delegates work but lists no skills",
        )

    missing = referenced - declared
    if missing:
        yield Finding(
            "F-024", "error", path,
            f"skills referenced in body but not in frontmatter `skills:`: {sorted(missing)}",
        )

    # F-016: heuristic — agent body should not contain knowledge artefacts
    if re.search(r"^\s*\|.*\|.*\|", body, re.MULTILINE):
        yield Finding("F-016", "warn", path, "agent body contains markdown table — likely embedded knowledge")
    code_blocks = re.findall(r"```[a-z]*\n(.*?)```", body, re.DOTALL)
    for cb in code_blocks:
        if cb.count("\n") > 8:
            yield Finding("F-016", "warn", path, "agent body contains code block >8 lines — move to skill")
            break
    if re.search(r"^###\s", body, re.MULTILINE):
        yield Finding("F-016", "warn", path, "agent body uses `###` heading — flatten or move to skill")

    # F-023: tools/disallowedTools disjoint
    tools = fm.get("tools") or []
    disallowed = fm.get("disallowedTools") or fm.get("disallowed_tools") or []
    if isinstance(tools, str):
        tools = tools.split()
    if isinstance(disallowed, str):
        disallowed = disallowed.split()
    overlap = set(tools) & set(disallowed)
    if overlap:
        yield Finding("F-023", "error", path, f"tools and disallowedTools overlap: {sorted(overlap)}")

    # F-025: worktree warning
    if fm.get("isolation") == "worktree":
        yield Finding(
            "F-025", "warn", path,
            "isolation: worktree — body must not assume parent worktree access",
        )

    # F-026: mcp_servers references exist
    mcp_field = fm.get("mcpServers") or fm.get("mcp_servers") or []
    if isinstance(mcp_field, list):
        for entry in mcp_field:
            if isinstance(entry, str) and entry not in mcp_servers:
                yield Finding(
                    "F-026", "error", path,
                    f"mcpServers references {entry!r} not configured in .mcp.json",
                )


# ---- rule rules ------------------------------------------------------------

_ALLOWED_RULE_KEYS = {"paths"}


def _lint_rule_file(path: Path) -> Iterator[Finding]:
    text = _safe_read(path)
    if text is None:
        return
    parsed = _parse_frontmatter(text)
    if parsed is not None:
        fm, body = parsed
        # F-028: only `paths:` allowed
        extras = set(fm.keys()) - _ALLOWED_RULE_KEYS
        if extras:
            yield Finding(
                "F-028", "error", path,
                f"rule frontmatter contains forbidden keys {sorted(extras)} (only `paths:` allowed)",
            )
        # F-006: paths is non-empty when present
        if "paths" in fm:
            paths = fm["paths"]
            if isinstance(paths, str):
                paths = [paths]
            if not paths:
                yield Finding("F-006", "error", path, "`paths:` field is empty")
    else:
        body = text  # entire body, no frontmatter

    # F-029: body opens with title
    body_stripped = body.lstrip()
    if not body_stripped.startswith("# "):
        yield Finding("F-029", "warn", path, "rule body should open with `# <Title>` heading")

    # F-030: body length
    nonblank = [line for line in body.splitlines() if line.strip()]
    if len(nonblank) > 50:
        yield Finding(
            "F-030", "warn", path,
            f"rule body is {len(nonblank)} non-blank lines (recommend ≤50; split into sub-files)",
        )


# ---- hook rules ------------------------------------------------------------


def _lint_hook_file(path: Path) -> Iterator[Finding]:
    if not path.is_file():
        return
    # F-012: executable bit
    # The POSIX execute bit does not exist on Windows (NTFS synthesises st_mode and
    # never sets S_IXUSR for regular files), so this check is meaningless there —
    # hooks run via `node script.mjs` regardless. Skip to avoid false positives.
    if os.name != "nt" and path.suffix in (".sh", ".mjs", ".py"):
        try:
            import stat
            if not (path.stat().st_mode & stat.S_IXUSR):
                yield Finding("F-012", "error", path, "hook script is not executable (run chmod +x)")
        except OSError:
            pass
    # F-040: prefer .mjs over .sh
    if path.suffix == ".sh":
        yield Finding(
            "F-040", "warn", path,
            "hook script is .sh — prefer .mjs (Node) for cross-platform portability",
        )


# ---- settings.json + .mcp.json rules ---------------------------------------

_DESTRUCTIVE_DENY_REQUIRED = {
    "Bash(rm -rf /:*)",
    "Bash(rm -rf ~:*)",
    "Bash(git push --force:*)",
    "Bash(git push --force-with-lease origin main:*)",
    "Read(./.env)",
    "Read(./**/*.pem)",
    "Read(./**/id_rsa)",
}

_ABS_PATH_RE = re.compile(r"(?:^|[\s\(])/(?:Users|home)/")


def _lint_settings(settings: dict, path: Path, mcp_servers: dict[str, dict]) -> Iterator[Finding]:
    perms = settings.get("permissions", {}) or {}
    allow = perms.get("allow", []) or []
    deny = perms.get("deny", []) or []

    # F-005: no absolute paths
    for rule in allow + deny + (perms.get("ask") or []):
        if isinstance(rule, str) and _ABS_PATH_RE.search(rule):
            yield Finding("F-005", "error", path, f"permission rule contains absolute path: {rule!r}")

    # F-008: governance/standard requires the destructive deny set
    deny_set = set(deny)
    missing = _DESTRUCTIVE_DENY_REQUIRED - deny_set
    if missing:
        yield Finding(
            "F-008", "error", path,
            f"governance baseline missing deny rules: {sorted(missing)}",
        )

    # F-010: MCP allow rules name servers that exist
    for rule in allow:
        if isinstance(rule, str) and rule.startswith("mcp__"):
            # rule like "mcp__atlassian__get_issue" → server is the second segment
            parts = rule[5:].split("__")
            if parts and parts[0] not in mcp_servers:
                yield Finding(
                    "F-010", "error", path,
                    f"permission rule {rule!r} references mcp server not in .mcp.json",
                )

    # hooks structural checks
    hooks = settings.get("hooks", {}) or {}
    if not isinstance(hooks, dict):
        yield Finding("F-033", "error", path, "settings.hooks must be a dict keyed by event")
        return
    for event, entries in hooks.items():
        if event not in _SUPPORTED_HOOK_EVENTS:
            yield Finding("F-033", "error", path, f"unsupported hook event {event!r}")
        if not isinstance(entries, list):
            continue
        for entry in entries:
            for handler in (entry.get("hooks") or []):
                yield from _lint_hook_handler(handler, path, mcp_servers, event)


_SUPPORTED_HOOK_EVENTS = {
    "SessionStart", "Setup", "UserPromptSubmit", "UserPromptExpansion",
    "PreToolUse", "PermissionRequest", "PermissionDenied",
    "PostToolUse", "PostToolUseFailure", "PostToolBatch",
    "Stop", "StopFailure",
    "SubagentStart", "SubagentStop", "TeammateIdle",
    "TaskCreated", "TaskCompleted",
    "Notification",
    "InstructionsLoaded", "ConfigChange",
    "CwdChanged", "FileChanged",
    "PreCompact", "PostCompact",
    "Elicitation", "ElicitationResult",
    "WorktreeCreate", "WorktreeRemove",
    "SessionEnd",
}

_NO_MATCHER_EVENTS = {
    "UserPromptSubmit", "Stop", "TeammateIdle", "TaskCreated", "TaskCompleted",
    "PostToolBatch", "WorktreeCreate", "WorktreeRemove", "CwdChanged",
}

_TOOL_EVENTS = {"PreToolUse", "PostToolUse", "PostToolUseFailure", "PermissionRequest", "PermissionDenied"}


def _lint_hook_handler(
    handler: dict, path: Path, mcp_servers: dict[str, dict], event: str
) -> Iterator[Finding]:
    htype = handler.get("type")
    # F-034: required fields per type
    required = {
        "command": ["command"],
        "http": ["url"],
        "mcp_tool": ["server", "tool"],
        "prompt": ["prompt"],
        "agent": ["prompt"],
    }
    if htype not in required:
        yield Finding("F-034", "error", path, f"unknown hook handler type {htype!r}")
        return
    for fld in required[htype]:
        if not handler.get(fld):
            yield Finding(
                "F-034", "error", path,
                f"hook handler type={htype!r} missing required field {fld!r}",
            )

    # F-038: mcp_tool.server exists
    if htype == "mcp_tool":
        server = handler.get("server")
        if server and server not in mcp_servers:
            yield Finding(
                "F-038", "error", path,
                f"hook references mcp server {server!r} not in .mcp.json",
            )

    # F-039: http headers $VAR refs declared in allowedEnvVars
    if htype == "http":
        headers = handler.get("headers") or {}
        allowed = set(handler.get("allowedEnvVars") or [])
        for hv in headers.values():
            for var in re.findall(r"\$([A-Z_][A-Z0-9_]*)", str(hv)):
                if var not in allowed:
                    yield Finding(
                        "F-039", "error", path,
                        f"http hook header references ${var} not in allowedEnvVars",
                    )

    # F-036: `if` filter on non-tool event
    if "if" in handler and event not in _TOOL_EVENTS:
        yield Finding(
            "F-036", "warn", path,
            f"`if` filter set on non-tool event {event!r} — silently ignored at runtime",
        )


def _lint_mcp(mcp_servers: dict[str, dict], path: Path) -> Iterator[Finding]:
    if not path.is_file():
        return
    for name, config in mcp_servers.items():
        env = config.get("env") or {}
        for k, v in env.items():
            if not isinstance(v, str):
                continue
            stripped = v.strip()
            if stripped == "":
                continue
            # heuristic: long opaque values look like literal tokens
            if (
                not stripped.startswith("$")
                and len(stripped) > 16
                and re.fullmatch(r"[A-Za-z0-9._\-/+=]+", stripped)
            ):
                yield Finding(
                    "F-007", "error", path,
                    f"mcpServers.{name}.env.{k} appears to be a literal token; use ${{ENV}} ref",
                )
        for hk, hv in (config.get("headers") or {}).items():
            if isinstance(hv, str) and "$" not in hv and len(hv) > 16:
                yield Finding(
                    "F-007", "error", path,
                    f"mcpServers.{name}.headers.{hk} appears to be a literal token; use ${{ENV}} ref",
                )


# ---- TODO counter ----------------------------------------------------------


def _lint_todos(project_dir: Path) -> Iterator[Finding]:
    pattern = re.compile(r"<!--\s*TODO\b.*?-->", re.IGNORECASE)
    for f in project_dir.rglob("*.md"):
        text = _safe_read(f)
        if text is None:
            continue
        count = len(pattern.findall(text))
        if count:
            yield Finding(
                "F-013", "warn", f, f"{count} TODO slot(s) unfilled",
            )


# ---- F-047..F-050: Requirement Phase v2 (plan §21) -------------------------


def _lint_story_priority_independent_test(project_dir: Path) -> Iterator[Finding]:
    """F-047: Stories with priority P1 must have independent_test: true.

    Scans `docs/stories/<id>.md` files alongside the harness — the linter only
    flags when the project actually has authored stories. The story-template
    skill carries the rule; this lint enforces it on the artefacts.
    """
    repo_root = project_dir.parent
    stories_dir = repo_root / "docs" / "stories"
    if not stories_dir.is_dir():
        return  # no authored stories yet — nothing to lint
    for story_path in stories_dir.glob("*.md"):
        text = _safe_read(story_path)
        if not text:
            continue
        priority_m = re.search(r"^\*\*Priority\*\*\s*:\s*(P[123])\s*$", text, re.MULTILINE)
        indep_m = re.search(r"^\*\*Independent test\*\*\s*:\s*(true|false)\s*$", text, re.MULTILINE)
        if not priority_m:
            continue
        priority = priority_m.group(1)
        independent = indep_m.group(1) if indep_m else None
        if priority == "P1" and independent != "true":
            yield Finding(
                "F-047", "warn", story_path,
                f"P1 story must have `Independent test: true` (found: {independent or 'missing'})",
            )


def _lint_state_file_schema_v2(project_dir: Path) -> Iterator[Finding]:
    """F-048: state records (index + per-feature) must use the v3 two-tier schema.

    Validates both:
      - INDEX: `docs/state/features.json` — every non-empty entry must carry
        `phase` and `last_updated` (status-mirror fields).
      - PER-FEATURE: `docs/features/<id>/state.json` — must carry `phase` and
        `last_updated`. Lives next to PRD / PLAN / DESIGN.

    Auto-migrate is the right fix for stale records; this lint surfaces the
    drift so commands know to re-emit. Empty `{}` index is fine. Missing
    per-feature files are fine — they only exist post-`/arh-plan-requirements`.

    `project_dir` here is the emitted-output root (typically `.claude/` for
    Claude Code or the equivalent target dir). Index and per-feature paths
    are computed relative to `project_dir.parent` because state lives under
    `docs/` (a sibling of `.claude/`).
    """
    # Find the docs/ root. In emitted layout, .claude/ and docs/ are siblings.
    docs_root = project_dir.parent / "docs"
    if not docs_root.is_dir():
        # Older layouts may put state directly under project_dir/state/. Try that.
        docs_root_alt = project_dir
        if (docs_root_alt / "state" / "features.json").is_file():
            docs_root = docs_root_alt

    v2_required = {"phase", "last_updated"}

    # 1. INDEX file
    index_file = docs_root / "state" / "features.json"
    if index_file.is_file():
        try:
            data = json.loads(index_file.read_text(encoding="utf-8"))
        except json.JSONDecodeError as e:
            yield Finding("F-048", "error", index_file, f"index file is not valid JSON: {e}")
            data = None
        if data is not None:
            if not isinstance(data, dict):
                yield Finding("F-048", "error", index_file, "index root must be an object")
            else:
                for feature_id, record in data.items():
                    if not isinstance(record, dict):
                        yield Finding(
                            "F-048", "error", index_file,
                            f"feature {feature_id!r}: record must be an object",
                        )
                        continue
                    missing = v2_required - set(record.keys())
                    if missing:
                        yield Finding(
                            "F-048", "warn", index_file,
                            f"feature {feature_id!r}: missing v2 fields {sorted(missing)} — auto-migrate on next command",
                        )

    # 2. PER-FEATURE files
    features_root = docs_root / "features"
    if features_root.is_dir():
        for child in sorted(features_root.iterdir()):
            if not child.is_dir():
                continue
            pf_state = child / "state.json"
            if not pf_state.is_file():
                continue  # pre-plan or non-feature dir
            try:
                record = json.loads(pf_state.read_text(encoding="utf-8"))
            except json.JSONDecodeError as e:
                yield Finding("F-048", "error", pf_state, f"per-feature state is not valid JSON: {e}")
                continue
            if not isinstance(record, dict):
                yield Finding(
                    "F-048", "error", pf_state,
                    "per-feature state root must be an object",
                )
                continue
            missing = v2_required - set(record.keys())
            if missing:
                yield Finding(
                    "F-048", "warn", pf_state,
                    f"missing v2 fields {sorted(missing)} — auto-migrate on next command",
                )


def _lint_sync_skill_required_refs(project_dir: Path) -> Iterator[Finding]:
    """F-049: /arh-sync skill body must reference requirement-tracing AND at least
    one provider integration skill (issue-tracking-* or doc-tracker-*).
    """
    sync_skill = project_dir / "skills" / "arh-sync" / "SKILL.md"
    if not sync_skill.is_file():
        return  # /arh-sync not emitted in this project
    text = _safe_read(sync_skill) or ""
    parsed = _parse_frontmatter(text)
    body = parsed[1] if parsed else text
    if "requirement-tracing" not in body:
        yield Finding(
            "F-049", "error", sync_skill,
            "sync SKILL.md must reference `requirement-tracing` skill",
        )
    has_provider_ref = bool(re.search(
        r"(issue-tracking-(jira|linear|github|azure)|doc-tracker-(confluence|notion))",
        body, re.IGNORECASE,
    ))
    if not has_provider_ref:
        yield Finding(
            "F-049", "error", sync_skill,
            "sync SKILL.md must reference at least one provider integration skill",
        )


def _lint_prd_open_questions_clarification_consistency(project_dir: Path) -> Iterator[Finding]:
    """F-050: A PRD with non-empty "Open questions" section must contain at
    least one [NEEDS CLARIFICATION] marker (consistency rule). Mismatch =
    bypass attempt or stale doc.
    """
    repo_root = project_dir.parent
    features_dir = repo_root / "docs" / "features"
    if not features_dir.is_dir():
        return
    prd_files = list(features_dir.glob("*/REQUIREMENTS.md"))
    for prd_path in prd_files:
        text = _safe_read(prd_path) or ""
        # Open questions section: header to next `## ` or end-of-file
        open_q_match = re.search(
            r"^##\s+Open questions\s*\n(.*?)(?=^##\s|\Z)",
            text, re.MULTILINE | re.DOTALL,
        )
        if not open_q_match:
            continue
        section = open_q_match.group(1)
        # Strip HTML comments and bullets to detect non-empty content
        body_only = re.sub(r"<!--.*?-->", "", section, flags=re.DOTALL).strip()
        # A bullet "- ..." with content (not just "- …" placeholder) counts as a non-empty entry
        bullets = [b for b in re.findall(r"^- (.+)$", body_only, re.MULTILINE)
                   if b.strip() and b.strip() not in ("…", "...")]
        if not bullets:
            continue
        # Section non-empty: require at least one [NEEDS CLARIFICATION] marker somewhere in body
        markers = re.findall(r"\[NEEDS CLARIFICATION:[^\]]*\]", text)
        if not markers:
            yield Finding(
                "F-050", "warn", prd_path,
                "Open questions has entries but no [NEEDS CLARIFICATION] markers in body — inconsistent",
            )


# ---- F-051: PRD / PLAN section pinning (plan §24) --------------------------

# Canonical pinned PRD section list (in order). Conditional sections marked.
_PRD_REQUIRED_SECTIONS = [
    "Problem",
    "Outcome",
    "Constraints",
    "Solution sketch",
    "Scope",
    "Functional requirements",
    "Non-functional requirements",
    "Rollout plan",
    "Documentation requirements",
    "Open questions",
    "Approvals",
]
# Optional: emitted only under specific conditions
_PRD_OPTIONAL_SECTIONS = {
    "Addressing Research Conditions",  # only when research_verdict == GO-WITH-CONDITIONS
    "Visual spec",                      # only for frontend/mobile roles
}

# Canonical pinned PLAN section list (in order). Section numbering is part of the header.
_PLAN_REQUIRED_SECTIONS = [
    "1. Architecture Decisions",
    "2. File and Module Plan",
    "3. Module Hierarchy",
    "4. State and Data Management",
    "5. Task Breakdown",
    "6. Carry-Forward Risks and Conditions",
    "7. Test Strategy",
]
# The "Plan validation" closing block is emitted by the plan-authoring rubric step after the seven sections.
_PLAN_TRAILING_SECTIONS = {"Plan validation"}


def _extract_h2_sections(text: str) -> list[str]:
    """Return the list of top-level `## ` section names in order, stripped of leading/trailing whitespace."""
    return [m.group(1).strip() for m in re.finditer(r"^##\s+(.+?)\s*$", text, re.MULTILINE)]


def _lint_prd_plan_section_pinning(project_dir: Path) -> Iterator[Finding]:
    """F-051 (warn): emitted REQUIREMENTS.md and PLAN.md must use the pinned section list.

    Deviation = renamed section, missing required section, extra unknown section,
    or out-of-order sections. Conditional sections (Addressing Research Conditions,
    Visual spec, Plan validation) are allowed but must appear in their pinned position
    when present.
    """
    repo_root = project_dir.parent
    features_dir = repo_root / "docs" / "features"
    if not features_dir.is_dir():
        return

    # PRD check
    for prd_path in features_dir.glob("*/REQUIREMENTS.md"):
        text = _safe_read(prd_path) or ""
        got = _extract_h2_sections(text)
        if not got:
            continue
        missing = [s for s in _PRD_REQUIRED_SECTIONS if s not in got]
        unknown = [s for s in got
                   if s not in _PRD_REQUIRED_SECTIONS and s not in _PRD_OPTIONAL_SECTIONS]
        if missing:
            yield Finding(
                "F-051", "warn", prd_path,
                f"PRD section pinning: missing required sections {missing!r}",
            )
        if unknown:
            yield Finding(
                "F-051", "warn", prd_path,
                f"PRD section pinning: unknown sections {unknown!r} (rename or move into a pinned section)",
            )

    # PLAN check
    for plan_path in features_dir.glob("*/PLAN.md"):
        text = _safe_read(plan_path) or ""
        got = _extract_h2_sections(text)
        if not got:
            continue
        missing = [s for s in _PLAN_REQUIRED_SECTIONS if s not in got]
        unknown = [s for s in got
                   if s not in _PLAN_REQUIRED_SECTIONS and s not in _PLAN_TRAILING_SECTIONS]
        if missing:
            yield Finding(
                "F-051", "warn", plan_path,
                f"PLAN section pinning: missing required sections {missing!r}",
            )
        if unknown:
            yield Finding(
                "F-051", "warn", plan_path,
                f"PLAN section pinning: unknown sections {unknown!r} (rename or fold into pinned sections)",
            )
        # Order check: required sections must appear in the canonical order
        seen_required_in_order = [s for s in got if s in _PLAN_REQUIRED_SECTIONS]
        expected_order = [s for s in _PLAN_REQUIRED_SECTIONS if s in seen_required_in_order]
        if seen_required_in_order != expected_order:
            yield Finding(
                "F-051", "warn", plan_path,
                f"PLAN section pinning: sections out of canonical order. "
                f"got={seen_required_in_order!r}, expected={expected_order!r}",
            )


# ---- F-052: context-economy mechanism present ------------------------------

def _lint_context_economy_present(
    project_dir: Path, settings: dict | None
) -> Iterator[Finding]:
    """F-052 (warn): the read-dedup hook + context-economy rule must ship.

    File Reads are the largest driver of resident context (the same spec/state
    files get re-Read 10–30x per session). Two surfaces keep that in check:
    a `post-read-dedup.mjs` PostToolUse hook (matcher Read) that elides identical
    re-reads, and a `context-economy` rule that tells agents not to issue them.
    This rule fails if either is dropped, so the savings cannot silently erode.
    """
    hook = project_dir / "hooks" / "post-read-dedup.mjs"
    if not hook.is_file():
        yield Finding(
            "F-052", "warn", hook,
            "read-dedup hook missing — re-read context savings unprotected",
        )
    else:
        registered = False
        for entry in ((settings or {}).get("hooks", {}).get("PostToolUse") or []):
            if entry.get("matcher") != "Read":
                continue
            for handler in (entry.get("hooks") or []):
                if "post-read-dedup.mjs" in (handler.get("command") or ""):
                    registered = True
        if not registered:
            yield Finding(
                "F-052", "warn", project_dir / "settings.json",
                "post-read-dedup.mjs not registered on PostToolUse (matcher 'Read')",
            )

    rule = project_dir / "rules" / "context-economy.md"
    if not rule.is_file():
        yield Finding(
            "F-052", "warn", rule,
            "context-economy rule missing — agents not told to avoid re-reads",
        )
